CREATE TABLE IF NOT EXISTS library_ai_zone_candidates_v2 (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(), document_id UUID REFERENCES library_documents(id), page_anchor_id UUID REFERENCES library_page_anchors_v2(page_anchor_id), pdf_page INTEGER NOT NULL, candidate_run_id TEXT NOT NULL, candidate_source TEXT NOT NULL, detection_origin TEXT NOT NULL, detection_model TEXT, candidate_page_kind TEXT, candidate_kind TEXT NOT NULL, candidate_marker_value TEXT, candidate_confidence NUMERIC, candidate_quote TEXT, raw_candidate JSONB NOT NULL, document_part TEXT, structural_status TEXT, is_blank BOOLEAN NOT NULL DEFAULT false, validation_run_id TEXT NOT NULL, validation_policy_version TEXT NOT NULL, validation_decision TEXT NOT NULL CHECK(validation_decision IN ('promote_candidate','keep_as_candidate','needs_human_review','reject_candidate')), can_write_authoritative BOOLEAN NOT NULL DEFAULT false CHECK(can_write_authoritative=false), validation_reasons JSONB NOT NULL DEFAULT '[]', validation_warnings JSONB NOT NULL DEFAULT '[]', review_status TEXT NOT NULL DEFAULT 'pending' CHECK(review_status IN ('pending','accepted_for_future_promotion','rejected_by_review','needs_more_context','superseded','not_required')), source_report_path TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(candidate_run_id,pdf_page,candidate_kind,candidate_quote));
CREATE INDEX IF NOT EXISTS idx_ai_zone_candidates_queue ON library_ai_zone_candidates_v2(validation_decision,review_status,pdf_page);
CREATE OR REPLACE VIEW library_ai_zone_candidate_review_queue_v2 AS SELECT id,pdf_page,document_part,structural_status,candidate_kind,candidate_marker_value,candidate_confidence,candidate_quote,validation_decision,validation_reasons,validation_warnings,review_status,detection_model,source_report_path,created_at FROM library_ai_zone_candidates_v2;
CREATE OR REPLACE VIEW library_ai_zone_candidate_summary_v2 AS SELECT validation_decision,review_status,candidate_kind,document_part,detection_origin,detection_model,count(*) AS candidates FROM library_ai_zone_candidates_v2 GROUP BY 1,2,3,4,5,6;
